package com.minenorth_eurobank.braquage.client; import net.minecraft.client.Minecraft; import java.util.List; public final class ClientNetworkHandler{private ClientNetworkHandler(){} public static void openHack(List<Integer>s){Minecraft.getInstance().setScreen(new HackingScreen(s));} public static void closeHack(){if(Minecraft.getInstance().screen instanceof HackingScreen)Minecraft.getInstance().setScreen(null);} public static void setProgress(int i,int t){if(Minecraft.getInstance().screen instanceof HackingScreen h)h.setProgress(i,t);}}
